def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    out = [row[:] for row in grid]
    if not points:
        return out

    ys = sorted(r for r, c in points)
    xs = sorted(c for r, c in points)
    my, mx = ys[len(ys) // 2], xs[len(xs) // 2]

    horizontal_cost = max(xs) - min(xs) + sum(abs(r - my) for r, c in points)
    vertical_cost = max(ys) - min(ys) + sum(abs(c - mx) for r, c in points)

    def paint(r, c):
        if out[r][c] == 0:
            out[r][c] = 3

    if horizontal_cost <= vertical_cost:
        for c in range(min(xs), max(xs) + 1):
            paint(my, c)
        for r, c in points:
            for rr in range(min(r, my), max(r, my) + 1):
                paint(rr, c)
    else:
        for r in range(min(ys), max(ys) + 1):
            paint(r, mx)
        for r, c in points:
            for cc in range(min(c, mx), max(c, mx) + 1):
                paint(r, cc)

    return out
